struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float sdSphere(float3 p, float r) { return length(p) - r; }
float sdPlane(float3 p) { return p.y + 0.5; }

float scene(float3 p)
{
    float t = time_sim_ms * 0.001;
    float3 sp = p - float3(0, 0.3 + sin(t) * 0.3, 0);
    float sphere = sdSphere(sp, 0.5);
    float plane = sdPlane(p);
    return min(sphere, plane);
}

float3 calcNormal(float3 p)
{
    float2 e = float2(0.001, 0.0);
    return normalize(float3(
        scene(p + e.xyy) - scene(p - e.xyy),
        scene(p + e.yxy) - scene(p - e.yxy),
        scene(p + e.yyx) - scene(p - e.yyx)));
}

float4 PSMain(VSOut i) : SV_Target
{
    float2 uv = i.uv * 2.0 - 1.0;
    float aspect = resolution_x / max(1.0, resolution_y);
    uv.x *= aspect;
    float3 ro = float3(0, 0.5, -3.0);
    float3 rd = normalize(float3(uv, 1.5));
    float totalDist = 0.0;
    float3 col = float3(0.1, 0.1, 0.15);
    for (int s = 0; s < 80; s++) {
        float3 p = ro + rd * totalDist;
        float d = scene(p);
        if (d < 0.001) {
            float3 n = calcNormal(p);
            float3 lightDir = normalize(float3(0.5, 0.8, -0.3));
            float diff = max(dot(n, lightDir), 0.0);
            float spec = pow(max(dot(reflect(-lightDir, n), -rd), 0.0), 32.0);
            col = float3(0.8, 0.4, 0.2) * (0.15 + 0.85 * diff) + float3(1, 1, 1) * spec * 0.5;
            float shadow = 1.0;
            float3 sro = p + n * 0.01;
            float st = 0.0;
            for (int j = 0; j < 30; j++) {
                float sd = scene(sro + lightDir * st);
                if (sd < 0.001) { shadow = 0.3; break; }
                st += sd;
                if (st > 5.0) break;
            }
            col *= shadow;
            break;
        }
        totalDist += d;
        if (totalDist > 20.0) break;
    }
    return float4(col, 1.0);
}
